INSERT INTO guestbook (handle, message, created_at) VALUES
  ('Zero Cool', 'Crashed 1,507 systems, but hole 18 crashed ME. HACK THE PLANET!', now() - interval '28 days'),
  ('Acid Burn', 'Beat Zero Cool by two strokes. As usual, the girls are better than the boys.', now() - interval '27 days'),
  ('Elliot Alderson', 'Hello, friend. The windmill on 9 runs an unpatched firmware from 2003. I fixed it for you. You''re welcome.', now() - interval '21 days'),
  ('Mr. Robot', 'The top 1% of the top 1% still can''t clear the Firewall in one. Beautiful.', now() - interval '21 days'),
  ('The Plague', 'There is no right and wrong. There''s only par... and everyone else. Send me your scorecards. RABBIT, FLU SHOT.', now() - interval '19 days'),
  ('Cereal Killer', 'FYI man, alright: you could sit at home and putt into a mug, or you could come here and putt into THE GIBSON.', now() - interval '18 days'),
  ('Hackerman', 'With the right form, you can putt so hard you hack time itself. I birdied hole 10 yesterday. Tomorrow.', now() - interval '12 days'),
  ('David Lightman', 'A strange game. The only winning move is... actually no, hole 13 is rigged, I checked.', now() - interval '9 days'),
  ('Trinity', 'Dodged all forty chutes on 16. The DoS hole is a joke when you know there is no ball.', now() - interval '5 days'),
  ('Neo', 'Whoa.', now() - interval '5 days'),
  ('Lisbeth Salander', 'Found three vulns in the scoreboard. Kept root. Fixed nothing. Par is a social construct.', now() - interval '2 days');
